#!/usr/bin/env bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
# Installs VRChat Auto-Rejoin for the current user (no root).
#   If VR Auto Launcher is installed, it is added there (starts with VRChat, stops after it).
#   Otherwise a systemd user service runs it in the background.
#   --service      use the systemd service even if VR Auto Launcher is installed
#   --no-start     only copy files (no launcher entry, no service)
set -euo pipefail
SRC="$(cd "$(dirname "$0")" && pwd)"
APP="$HOME/.local/share/vrchat-auto-rejoin"
BIN="$HOME/.local/bin"
LAUNCHER_CFG="$HOME/.config/vr-autolauncher/config.json"
UNIT="$HOME/.config/systemd/user/vrchat-auto-rejoin.service"
MODE=auto
for a in "$@"; do
  case "$a" in --service) MODE=service ;; --no-start) MODE=none ;; esac
done

say() { echo "• $*"; }
command -v python3 >/dev/null || { echo "python3 is required / потрібен python3"; exit 1; }

say "Copying files / Копіюю файли → $APP"
mkdir -p "$APP" "$BIN" "$HOME/.local/share/applications"
cp "$SRC/auto_rejoin.py" "$SRC/vrchat_kicks.py" "$SRC/LICENSE" "$SRC/NOTICE" \
   "$SRC/uninstall.sh" "$SRC/vrchat-auto-rejoin.service" "$APP/"
python3 -I -B -c "import sys; sys.path.insert(0, '$APP'); import auto_rejoin; print(auto_rejoin.VERSION)" \
  > "$APP/VERSION" 2>/dev/null || true

cat > "$BIN/vrchat-auto-rejoin" <<SH
#!/bin/sh
exec python3 -I "$APP/auto_rejoin.py" "\$@"
SH
cat > "$BIN/vrchat-kicks" <<SH
#!/bin/sh
exec python3 -I "$APP/vrchat_kicks.py" "\$@"
SH
chmod +x "$BIN/vrchat-auto-rejoin" "$BIN/vrchat-kicks"

cat > "$HOME/.local/share/applications/vrchat-kicks.desktop" <<DESK
[Desktop Entry]
Type=Application
Name=VRChat kicks
Name[uk]=Вильоти VRChat
Comment=When and why VRChat kicked you, and what auto-rejoin did
Comment[uk]=Коли і чому викидало з інстансу, і що зробило авто-повернення
Exec=$BIN/vrchat-kicks
Icon=network-error
Categories=Game;Utility;
StartupWMClass=vrchat-kicks
DESK

if ! python3 -c "import PySide6" 2>/dev/null; then
  say "Installing PySide6 for the log window / Встановлюю PySide6 для вікна журналу"
  python3 -m pip install -q --user --disable-pip-version-check PySide6 2>/dev/null || \
    echo "  ! Could not install PySide6. The rejoin works anyway; for the window run e.g." \
         "'sudo dnf install python3-pyside6' / вікну потрібен PySide6"
fi

stop_service() {
  if [ -f "$UNIT" ]; then
    systemctl --user disable --now vrchat-auto-rejoin.service 2>/dev/null || true
    rm -f "$UNIT"
    systemctl --user daemon-reload 2>/dev/null || true
  fi
}

if [ "$MODE" = auto ] && [ -f "$LAUNCHER_CFG" ]; then
  say "Adding to VR Auto Launcher / Додаю в VR Auto Launcher (starts with VRChat)"
  stop_service
  pkill -x vrchat-rejoin 2>/dev/null || true   # an old copy; the launcher starts the new one
  python3 -I - "$LAUNCHER_CFG" <<'PY'
import json, os, sys
path = sys.argv[1]
cfg = json.load(open(path, encoding="utf-8"))
apps = cfg.setdefault("apps", [])
uk = os.environ.get("LANG", "").startswith("uk")
entry = {
    "name": "VRChat авто-повернення" if uk else "VRChat auto-rejoin",
    "enabled": True,
    "when": ["vrchat"],
    "trigger": "all",
    "delay": 0,
    "command": "~/.local/bin/vrchat-auto-rejoin",
    "running": ["vrchat-rejoin"],
    "close_on_exit": True,
    "close_delay": 180,   # it restarts VRChat itself — don't stop it during that
    "keep_alive": True,
    "env": {},
}
for a in apps:
    if "vrchat-auto-rejoin" in a.get("command", "") or "auto_rejoin.py" in a.get("command", ""):
        a.update({k: entry[k] for k in ("command", "running", "when", "close_delay")})
        break
else:
    apps.append(entry)
tmp = path + ".tmp"
with open(tmp, "w", encoding="utf-8") as f:
    json.dump(cfg, f, ensure_ascii=False, indent=2)
os.replace(tmp, path)
PY
elif [ "$MODE" != none ]; then
  say "Background service / Служба у фоні (systemd --user)"
  mkdir -p "$(dirname "$UNIT")"
  cp "$SRC/vrchat-auto-rejoin.service" "$UNIT"
  systemctl --user daemon-reload
  systemctl --user enable vrchat-auto-rejoin.service >/dev/null 2>&1
  systemctl --user restart vrchat-auto-rejoin.service
fi

echo
echo "Done / Готово. Log window: menu → «VRChat kicks» / «Вильоти VRChat»"
echo "Uninstall / Видалити: bash $APP/uninstall.sh"
